+	p, err := c.node(n.parents[i])
+	if err != nil {
+		return nil, err
+	}
+	if n.parentNodes == nil {
+		n.parentNodes = make([]*commitNode, len(n.parents))
+	}
+	n.parentNodes[i] = p
+	n.resolved = i + 1
+	return p, nil
+}
